[[/=]]

[[div style="text-align: center; margin-top: -20px;"]]

[[size 90%]]##757575|by Rhys Tanner and A Fungus##[[/size]]

[[/div]]

[[include <a href="https://scp-wiki.wikidot.com/component:image-features-source">:scp-wiki:component:image-features-source</a> |hover-enlarge=--]

|enlarge-amount=10

|speed=500

|float=true

|align=right

|width=33%

